def synthetic_application_environment(values):
    return {
        **{name: value for name, value in values.items() if name not in APPLICATION_NAMES},
        **DEFAULT_ENV,
        "APP_ENV": "test",
    }


def guard_project_dotenv(loader):
    def guarded(dotenv_path=None, *args, **kwargs):
        if dotenv_path is not None:
            protected = {Path(os.path.abspath(path)) for path in PROTECTED_DOTENV_PATHS}
            # Keep checkout filenames blocked without inspecting their symlink targets.
            if Path(os.path.abspath(dotenv_path)) in protected:
                return False
            # Also block aliases/targets; recalculate so a switched symlink stays protected.
            resolved = Path(dotenv_path).resolve()
            if resolved in {path.resolve() for path in protected}:
                return False
        return loader(dotenv_path, *args, **kwargs)
    return guarded
